create table if not exists public.notification_deliveries (id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.notification_events(id) on delete cascade,recipient_user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in ('in_app','push')),status text not null default 'queued' check(status in ('queued','sent','failed','skipped','expired')),attempts integer not null default 0,available_at timestamptz not null default now(),sent_at timestamptz,error text,created_at timestamptz not null default now()); create unique index if not exists uq_notification_delivery_recipient_channel on public.notification_deliveries(notification_id,recipient_user_id,channel); create index if not exists idx_notification_deliveries_queue on public.notification_deliveries(status,available_at); create index if not exists idx_notification_deliveries_recipient on public.notification_deliveries(recipient_user_id,created_at desc); alter table public.notification_deliveries enable row level security; create policy notification_deliveries_own_read on public.notification_deliveries for select to authenticated using(recipient_user_id=auth.uid()); create or replace function public.queue_notification_delivery(p_notification_id uuid,p_recipient_user_id uuid,p_channel text default 'in_app') returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin insert into public.notification_deliveries(notification_id,recipient_user_id,channel) values(p_notification_id,p_recipient_user_id,p_channel) on conflict(notification_id,recipient_user_id,channel) do update set status=case when notification_deliveries.status='failed' then 'queued' else notification_deliveries.status end,available_at=now() returning id into v_id; return v_id; end; $$;
